insert into public.pts_pts(id,dados) values ('ex1',$j${"id": "ex1", "prontuario": "00123", "nome": "(Exemplo) João Pedro Almeida", "nasc": "2017-03-14", "ensino": "sim", "hipotese": "Paralisia cerebral espástica bilateral (diplegia) – GMFCS II", "respId": "5a8effc4-e813-480f-94ec-235f0144b1cb", "objPaciente": "Família deseja que ele consiga andar na escola sem cair e subir no ônibus sozinho. Quer ser mais bem compreendido pelos colegas quando fala.", "therasuit": "sim", "aquatica": "nao", "prazo": "2026-11-09", "criadoEm": "2026-10-29T19:28:38.211Z", "assinadoEm": null, "dataExplicacao": "", "equipe": {"fisio": "5a8effc4-e813-480f-94ec-235f0144b1cb", "fono": "2b703100-5690-4884-8173-693235170289", "nutri": null, "psico": "88739d63-16df-4525-8879-090ce9ea3150", "to": "3b1d73be-d3c2-484e-b922-150dc5192a3f"}}$j$::jsonb) on conflict (id) do nothing;
insert into public.pts_extra(pts_id,dados) values ('ex1',$j${"diag": {"end": {"logradouro": "Rua das Garças (exemplo)", "numero": "120", "complemento": "", "bairro": "Jardim Aero Rancho", "regiao": "", "cep": "", "telefone": "(67) 90000-0000", "referencia": "Perto da praça (exemplo)"}, "textos": {"historico": "Nasceu prematuro (32 semanas), com diagnóstico de PC aos 14 meses. Acompanha no CER desde 2019. Família relata piora das quedas desde que mudou de escola, no início do ano.", "contexto": "Mora com os pais, a irmã mais velha e a avó materna. A mãe é a cuidadora principal e deixou o emprego para acompanhar as terapias. Vão ao CER de ônibus (cerca de 50 min).", "rotina": "Cursa o 3º ano em escola municipal, no período da manhã. Recebe BPC. Gosta de futebol e desenho.", "acoes": "Fisioterapia e fonoaudiologia no CER desde 2019. Aplicação de toxina botulínica em 2025. Órteses suropodálicas renovadas em 2026.", "vulnerabilidades": "Sobrecarga da mãe. Distância e tempo de deslocamento até o CER. Escola sem adaptações de acessibilidade no pátio.", "potencialidades": "Muito motivado pelo futebol. Avó participa ativamente do cuidado. Bom vínculo com a professora. Família presente nas terapias."}, "familia": [{"id": "wn72s7i", "nome": "Marcos Almeida", "par": "pai", "idade": "38", "moraJunto": true}, {"id": "twqekm5", "nome": "Juliana Almeida", "par": "mae", "idade": "35", "moraJunto": true, "cuidador": true}, {"id": "903gz2o", "nome": "Beatriz", "par": "irmao", "sexo": "F", "idade": "13", "moraJunto": true}, {"id": "ik03d90", "nome": "Dona Lourdes", "par": "avo_mf", "idade": "67", "moraJunto": true}, {"id": "2gs1qqq", "nome": "Sr. Antônio", "par": "avo_mm", "idade": "", "falecido": true}], "rede": [{"id": "5khwohs", "dirId": "u68", "tipo": "UBS", "nome": "USF Dra. Regia Jussara F. de Barros – Aero Rancho Granja", "endereco": "Rua do Príncipe, s/n (esq. Rua Alagoinha)", "bairro": "Jardim Aero Rancho", "telefone": "(67) 2020-2119", "vinculo": "moderado", "obs": "Vacinação e consultas"}, {"id": "p1h80u1", "dirId": "c05", "tipo": "CRAS", "nome": "CRAS Profª Adevair Costa Lolli Gueti – Aero Rancho", "endereco": "Rua Globo de Ouro, 862", "bairro": "Aero Rancho", "telefone": "(67) 3314-6410", "vinculo": "fraco", "obs": "BPC; nunca foi a grupos"}, {"id": "invyoke", "tipo": "CER/APAE", "nome": "CER – APAE", "vinculo": "forte", "obs": "Fisio, fono, psico e TO"}, {"id": "ap6mkbr", "tipo": "Escola", "nome": "Escola Municipal (exemplo)", "vinculo": "moderado", "obs": "Professora parceira; pátio sem acessibilidade"}, {"id": "czf6mtl", "tipo": "Religião", "nome": "Igreja do bairro", "vinculo": "forte", "obs": "Família frequenta aos domingos"}, {"id": "cp9895g", "tipo": "Família extensa", "nome": "Tios paternos", "vinculo": "conflituoso", "obs": ""}], "sexoPac": "M", "uniaoPais": ""}, "plano": [{"id": "zd2ymiy", "acao": "Programa domiciliar de alongamento de tríceps sural, orientado à família", "resp": "Hugo Machado (Fisioterapia) / Família", "prazo": "Contínuo", "situacao": "em andamento"}, {"id": "860zdi7", "acao": "Visita à escola para orientar adaptações no pátio e nas aulas de educação física", "resp": "Camila Benites (Terapia Ocupacional)", "prazo": "60 dias", "situacao": "a iniciar"}, {"id": "m9bgndt", "acao": "Encaminhar a mãe para grupo de cuidadores do CRAS", "resp": "Diego Ferraz (Psicologia) / CRAS Aero Rancho", "prazo": "30 dias", "situacao": "a iniciar"}, {"id": "7u0b4pg", "acao": "Contrarreferência para a USF: acompanhamento de vacinação e crescimento", "resp": "Responsável pelo PTS / USF", "prazo": "30 dias", "situacao": "a iniciar"}], "pact": {"data": "", "profId": "5a8effc4-e813-480f-94ec-235f0144b1cb", "comQuem": "João Pedro e a mãe", "combinado": "", "ajustes": ""}, "govBase": null}$j$::jsonb) on conflict do nothing;
insert into public.pts_areas(pts_id,area,dados) values ('ex1','fisio',$j${"medio": "Melhorar o equilíbrio dinâmico e a resistência na marcha, reduzindo quedas no ambiente escolar; ganhar ADM de dorsiflexão com programa domiciliar de alongamento orientado à família.", "longo": "Marcha comunitária independente em terrenos irregulares e subida/descida de degraus de ônibus com apoio de corrimão, sem auxílio de terceiros.", "concluidoEm": "2026-11-02T19:28:38.211Z", "atualizadoEm": "2026-11-02T19:28:38.211Z", "assinatura": {"profId": "5a8effc4-e813-480f-94ec-235f0144b1cb", "nome": "Hugo Machado", "registro": "CREFITO 000000-F", "em": "2026-11-02T19:28:38.211Z", "img": null, "modo": "texto", "hash": "5b97e16e263af4c3e3b423125cc9c468038820ff0ba47652d71287cd768fd8c2", "codigo": "5B97-E16E"}}$j$::jsonb) on conflict do nothing;
