insert into public.pts_mensagens(id,pts_id,autor_id,dados,em) values ('79qqb9y','ex1','5a8effc4-e813-480f-94ec-235f0144b1cb',$j${"id": "79qqb9y", "autorId": "5a8effc4-e813-480f-94ec-235f0144b1cb", "texto": "Pessoal, abri o PTS do João Pedro. A família trouxe como principal queixa as quedas no recreio e a dificuldade de subir no ônibus escolar. Indiquei Therasuit.", "em": "2026-10-29T19:28:38.212Z"}$j$::jsonb,'2026-10-29T19:28:38.212Z') on conflict do nothing;
insert into public.pts_mensagens(id,pts_id,autor_id,dados,em) values ('fp68q41','ex1','2b703100-5690-4884-8173-693235170289',$j${"id": "fp68q41", "autorId": "2b703100-5690-4884-8173-693235170289", "texto": "Preenchi a parte da fono. A mãe comentou que ele tem evitado falar na sala por vergonha. Diego, vale olhar isso também?", "em": "2026-11-01T19:28:38.212Z"}$j$::jsonb,'2026-11-01T19:28:38.212Z') on conflict do nothing;
